// Coffee M&A Newsletter Processor v2.0
// MEJORADO: Incluye seguimiento específico de competidores de Libertario

const allItems = $input.all();
const currentDate = new Date();
const oneWeekAgo = new Date(currentDate.getTime() - 7 * 24 * 60 * 60 * 1000);

// Helpers
const fmt = (n, d=2) => (n === null || n === undefined || isNaN(n)) ? 'N/A' : parseFloat(n).toFixed(d);
const pct = (c, p) => (!p || p === 0 || !c) ? null : ((c - p) / p * 100).toFixed(2);
const clean = (t) => t ? t.replace(/<[^>]*>/g, '').replace(/&[^;]+;/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 400) : '';

const extractHostname = (url) => {
  if (!url) return 'Unknown';
  const match = url.match(/^(?:https?:\/\/)?(?:www\.)?([^\/:?#]+)/i);
  return match ? match[1] : 'Unknown';
};

// Palabras clave para M&A
const maKeywords = [
  'acquisition', 'acquires', 'acquired', 'acquire',
  'merger', 'merge', 'merged', 'merging',
  'investment', 'invests', 'invested', 'investor',
  'funding', 'funded', 'raises', 'raised',
  'series a', 'series b', 'series c', 'seed round',
  'private equity', 'venture capital', 'vc',
  'buyout', 'buy out', 'bought',
  'partnership', 'partners', 'joint venture',
  'expansion', 'expands', 'expanding', 'opens', 'opening', 'launch', 'launches',
  'sale', 'sells', 'sold', 'selling',
  'ipo', 'public offering', 'spac',
  'valuation', 'valued at',
  'stake', 'shares', 'equity',
  'deal', 'transaction', 'agreement',
  'convertible', 'notes', 'debt', 'financing',
  'adquisición', 'adquiere', 'fusión', 'inversión',
  'financiamiento', 'expansión', 'compra', 'venta',
  'new store', 'new location', 'new roastery', 'new cafe'
];

// ============================================
// COMPETIDORES DE LIBERTARIO COFFEE ROASTERS
// ============================================
const competitors = {
  // India - Mercado emergente muy activo
  'blue tokai': { name: 'Blue Tokai Coffee', region: 'India', type: 'roaster_chain', priority: 'high' },
  'blue tokai coffee': { name: 'Blue Tokai Coffee', region: 'India', type: 'roaster_chain', priority: 'high' },
  'third wave coffee': { name: 'Third Wave Coffee', region: 'India', type: 'chain', priority: 'high' },
  'thirdwave': { name: 'Third Wave Coffee', region: 'India', type: 'chain', priority: 'high' },
  'subko': { name: 'Subko Coffee', region: 'India', type: 'roaster', priority: 'high' },
  'subko coffee': { name: 'Subko Coffee', region: 'India', type: 'roaster', priority: 'high' },

  // USA - Competidores directos
  'blank street': { name: 'Blank Street Coffee', region: 'USA/UK', type: 'chain', priority: 'high' },
  'blankstreet': { name: 'Blank Street Coffee', region: 'USA/UK', type: 'chain', priority: 'high' },
  'blank street coffee': { name: 'Blank Street Coffee', region: 'USA/UK', type: 'chain', priority: 'high' },
  'onyx coffee': { name: 'Onyx Coffee Lab', region: 'USA', type: 'roaster', priority: 'high' },
  'onyx coffee lab': { name: 'Onyx Coffee Lab', region: 'USA', type: 'roaster', priority: 'high' },
  'verve coffee': { name: 'Verve Coffee Roasters', region: 'USA', type: 'roaster', priority: 'medium' },
  'verve': { name: 'Verve Coffee Roasters', region: 'USA', type: 'roaster', priority: 'medium' },
  'devocion': { name: 'Devoción Coffee', region: 'Colombia/USA', type: 'roaster', priority: 'high' },
  'devoción': { name: 'Devoción Coffee', region: 'Colombia/USA', type: 'roaster', priority: 'high' },

  // Australia - Líderes en specialty
  'proud mary': { name: 'Proud Mary Coffee', region: 'Australia/USA', type: 'roaster_cafe', priority: 'high' },
  'proud mary coffee': { name: 'Proud Mary Coffee', region: 'Australia/USA', type: 'roaster_cafe', priority: 'high' },
  'market lane': { name: 'Market Lane Coffee', region: 'Australia', type: 'roaster', priority: 'medium' },
  'seven seeds': { name: 'Seven Seeds', region: 'Australia', type: 'roaster', priority: 'medium' },
  'ona coffee': { name: 'ONA Coffee', region: 'Australia', type: 'roaster', priority: 'medium' },

  // China - Mercado masivo
  'manner coffee': { name: 'Manner Coffee', region: 'China', type: 'chain', priority: 'high' },
  'manner': { name: 'Manner Coffee', region: 'China', type: 'chain', priority: 'high' },
  'luckin coffee': { name: 'Luckin Coffee', region: 'China', type: 'chain', priority: 'medium' },
  'luckin': { name: 'Luckin Coffee', region: 'China', type: 'chain', priority: 'medium' },

  // Scandinavia - Referentes de calidad
  'tim wendelboe': { name: 'Tim Wendelboe', region: 'Norway', type: 'roaster', priority: 'medium' },
  'koppi': { name: 'Koppi Coffee', region: 'Sweden', type: 'roaster', priority: 'medium' },
  'drop coffee': { name: 'Drop Coffee', region: 'Sweden', type: 'roaster', priority: 'medium' },

  // Japón/Asia
  '% arabica': { name: '% Arabica', region: 'Japan/Global', type: 'chain', priority: 'medium' },
  'percent arabica': { name: '% Arabica', region: 'Japan/Global', type: 'chain', priority: 'medium' },
  'arabica coffee': { name: '% Arabica', region: 'Japan/Global', type: 'chain', priority: 'medium' },

  // San Francisco specialty
  'sightglass': { name: 'Sightglass Coffee', region: 'USA', type: 'roaster', priority: 'medium' },
  'ritual coffee': { name: 'Ritual Coffee Roasters', region: 'USA', type: 'roaster', priority: 'medium' },
  'equator coffees': { name: 'Equator Coffees', region: 'USA', type: 'roaster', priority: 'medium' },

  // UK
  'origin coffee': { name: 'Origin Coffee', region: 'UK', type: 'roaster', priority: 'medium' },
  'square mile': { name: 'Square Mile Coffee', region: 'UK', type: 'roaster', priority: 'medium' }
};

// Compañías generales de la industria (para contexto)
const industryCompanies = [
  'westrock', 'jab holding', 'jde peets', 'starbucks', 'nestle', 'nespresso',
  'blue bottle', 'intelligentsia', 'stumptown', 'counter culture',
  'la colombe', 'dunkin', 'peets', 'lavazza', 'illy', 'illycaffè',
  'keurig', 'dr pepper', 'green mountain', 'caribou',
  'tim hortons', 'costa coffee',
  'cafe imports', 'royal coffee', 'genuine origin', 'sucafina',
  'olam', 'ecom', 'neumann kaffee', 'volcafe'
];

// Combinar todos para búsqueda
const allCompanies = [...Object.keys(competitors), ...industryCompanies];

// Traducción de términos M&A
const translateMA = (text) => {
  if (!text) return '';
  return text
    .replace(/\bacquisition\b/gi, 'adquisición')
    .replace(/\bacquires\b/gi, 'adquiere')
    .replace(/\bacquired\b/gi, 'adquirió')
    .replace(/\bmerger\b/gi, 'fusión')
    .replace(/\bmerges\b/gi, 'se fusiona')
    .replace(/\binvestment\b/gi, 'inversión')
    .replace(/\binvests\b/gi, 'invierte')
    .replace(/\bfunding\b/gi, 'financiamiento')
    .replace(/\braises\b/gi, 'recauda')
    .replace(/\braised\b/gi, 'recaudó')
    .replace(/\bprivate equity\b/gi, 'capital privado')
    .replace(/\bventure capital\b/gi, 'capital de riesgo')
    .replace(/\bbuyout\b/gi, 'compra')
    .replace(/\bpartnership\b/gi, 'alianza')
    .replace(/\bjoint venture\b/gi, 'empresa conjunta')
    .replace(/\bexpansion\b/gi, 'expansión')
    .replace(/\bexpands\b/gi, 'expande')
    .replace(/\bsale\b/gi, 'venta')
    .replace(/\bsells\b/gi, 'vende')
    .replace(/\bsold\b/gi, 'vendió')
    .replace(/\bIPO\b/gi, 'salida a bolsa')
    .replace(/\bpublic offering\b/gi, 'oferta pública')
    .replace(/\bstake\b/gi, 'participación')
    .replace(/\bshares\b/gi, 'acciones')
    .replace(/\bequity\b/gi, 'capital')
    .replace(/\bdeal\b/gi, 'acuerdo')
    .replace(/\btransaction\b/gi, 'transacción')
    .replace(/\bconvertible notes\b/gi, 'notas convertibles')
    .replace(/\bfinancing\b/gi, 'financiamiento')
    .replace(/\bcoffee roaster\b/gi, 'tostadora de café')
    .replace(/\bspecialty coffee\b/gi, 'café especial')
    .replace(/\bcoffee company\b/gi, 'empresa de café')
    .replace(/\bcoffee chain\b/gi, 'cadena de café')
    .replace(/\bmillion\b/gi, 'millones')
    .replace(/\bbillion\b/gi, 'mil millones')
    .replace(/\bvaluation\b/gi, 'valoración')
    .replace(/\bvalued at\b/gi, 'valorada en')
    .replace(/\bnew store\b/gi, 'nueva tienda')
    .replace(/\bnew location\b/gi, 'nueva ubicación');
};

// Función para calcular relevancia de M&A
const calculateMARelevance = (text) => {
  const lowerText = text.toLowerCase();
  let score = 0;

  maKeywords.forEach(keyword => {
    if (lowerText.includes(keyword)) score += 10;
  });

  // Puntos extra por competidores (prioridad alta)
  Object.entries(competitors).forEach(([key, info]) => {
    if (lowerText.includes(key)) {
      score += info.priority === 'high' ? 25 : 15;
    }
  });

  // Puntos por empresas de la industria
  industryCompanies.forEach(company => {
    if (lowerText.includes(company)) score += 10;
  });

  // Puntos por menciones de montos
  if (lowerText.match(/\$\d+/)) score += 5;
  if (lowerText.match(/million|billion|millones|mil millones/)) score += 5;

  return score;
};

// Detectar si la noticia es sobre un competidor específico
const detectCompetitor = (text) => {
  const lowerText = text.toLowerCase();
  const found = [];

  Object.entries(competitors).forEach(([key, info]) => {
    if (lowerText.includes(key)) {
      // Evitar duplicados por nombre normalizado
      if (!found.find(c => c.name === info.name)) {
        found.push(info);
      }
    }
  });

  return found;
};

// Categorización de noticias
const categorizeNews = (text, competitorsFound) => {
  const lower = text.toLowerCase();

  // Si es sobre un competidor, marcar como tal
  if (competitorsFound && competitorsFound.length > 0) return 'competitors';

  if (lower.match(/acquisition|acquires|acquired|buyout|bought|compra|adquiere/)) return 'acquisitions';
  if (lower.match(/merger|merge|fusion|fusión/)) return 'mergers';
  if (lower.match(/investment|invests|funding|raises|series|seed|venture|inversión|financiamiento/)) return 'investments';
  if (lower.match(/expansion|expands|opens|launch|new location|new store|expansión/)) return 'expansions';
  if (lower.match(/partnership|partners|joint venture|alliance|alianza/)) return 'partnerships';
  if (lower.match(/ipo|public|spac|stock|shares|bolsa/)) return 'public_markets';
  if (lower.match(/sale|sells|sold|divest|venta|vende/)) return 'divestitures';

  return 'general';
};

// Data structure
const data = {
  reportDate: currentDate.toLocaleDateString('es-CO', { 
    weekday: 'long', 
    year: 'numeric', 
    month: 'long', 
    day: 'numeric',
    timeZone: 'America/Bogota' 
  }),
  weekRange: {
    start: oneWeekAgo.toLocaleDateString('es-CO', { month: 'short', day: 'numeric' }),
    end: currentDate.toLocaleDateString('es-CO', { month: 'short', day: 'numeric' })
  },
  markets: {
    coffeeArabica: null,
    trm: null
  },
  news: {
    competitors: [],      // NUEVA CATEGORÍA: Noticias de competidores
    acquisitions: [],
    mergers: [],
    investments: [],
    expansions: [],
    partnerships: [],
    public_markets: [],
    divestitures: [],
    general: [],
    all_ma: [],
    top_stories: []
  },
  competitors: {
    mentioned: {},        // Contador de menciones por competidor
    news_by_company: {},  // Noticias agrupadas por competidor
    summary: ''           // Resumen de actividad de competidores
  },
  companies: {
    mentioned: {},
    deals_count: 0
  },
  summaries: {},
  statistics: {
    totalSources: allItems.length,
    maNewsCount: 0,
    competitorNewsCount: 0,
    totalDealsValue: 'Por determinar'
  }
};

// Process items
allItems.forEach(item => {
  const j = item.json;

  // Yahoo Finance Coffee Futures
  if (j?.chart?.result?.[0]) {
    const c = j.chart.result[0], m = c.meta, q = c.indicators?.quote?.[0];
    if (m && q) {
      const i = (q.close?.length || 1) - 1;
      const price = q.close?.[i], prev = m.chartPreviousClose || m.previousClose || q.close?.[i-1];
      const chg = price && prev ? price - prev : null;
      const chgPct = pct(price, prev);
      const mk = {
        price: fmt(price),
        change: chg !== null ? fmt(chg) : 'N/A',
        changePercent: chgPct ? chgPct + '%' : 'N/A',
        isPositive: chg > 0,
        isNegative: chg < 0
      };
      const s = m.symbol || '';
      if (s === 'KC=F' || s.includes('KC')) {
        data.markets.coffeeArabica = { ...mk, name: 'Café Arábica (ICE)' };
      }
    }
  }

  // TRM Colombia
  if (Array.isArray(j) && j[0]?.valor) {
    const trmValue = parseFloat(j[0].valor);
    data.markets.trm = {
      rate: trmValue,
      formatted: fmt(trmValue, 2),
      date: j[0].vigenciadesde || ''
    };
  }

  // RSS News Processing
  if (j?.title && (j?.link || j?.url)) {
    const rawContent = (j.title || '') + ' ' + (j.summary || j.description || j.contentSnippet || j.content || '');
    const maRelevance = calculateMARelevance(rawContent);

    if (maRelevance > 0) {
      const summary = clean(j.summary || j.description || j.contentSnippet || j.content || '');
      const pubDate = j.pubDate || j.isoDate || '';
      const newsDate = new Date(pubDate);

      if (newsDate >= oneWeekAgo || !pubDate) {
        // Detectar competidores mencionados
        const competitorsFound = detectCompetitor(rawContent);
        const category = categorizeNews(rawContent, competitorsFound);

        const news = {
          title: j.title?.slice(0, 200),
          titleEs: translateMA(j.title?.slice(0, 200)),
          link: j.link || j.url,
          source: j.source || j.creator || extractHostname(j.link || j.url),
          pubDate: pubDate,
          summary: summary,
          summaryEs: translateMA(summary),
          relevance: maRelevance,
          category: category,
          competitors: competitorsFound  // Lista de competidores mencionados
        };

        // Agregar a categoría correspondiente
        if (data.news[category]) {
          data.news[category].push(news);
        }
        data.news.all_ma.push(news);

        // Rastrear competidores mencionados
        competitorsFound.forEach(comp => {
          data.competitors.mentioned[comp.name] = (data.competitors.mentioned[comp.name] || 0) + 1;

          // Agrupar noticias por competidor
          if (!data.competitors.news_by_company[comp.name]) {
            data.competitors.news_by_company[comp.name] = {
              info: comp,
              news: []
            };
          }
          data.competitors.news_by_company[comp.name].news.push(news);
        });

        // Rastrear empresas de la industria
        industryCompanies.forEach(company => {
          if (rawContent.toLowerCase().includes(company)) {
            data.companies.mentioned[company] = (data.companies.mentioned[company] || 0) + 1;
          }
        });
      }
    }
  }
});

// Sort by relevance and limit
const sortByRelevance = (arr, n) => arr
  .filter(x => x.title)
  .sort((a, b) => b.relevance - a.relevance || new Date(b.pubDate || 0) - new Date(a.pubDate || 0))
  .slice(0, n);

data.news.competitors = sortByRelevance(data.news.competitors, 15);  // Más espacio para competidores
data.news.acquisitions = sortByRelevance(data.news.acquisitions, 10);
data.news.mergers = sortByRelevance(data.news.mergers, 5);
data.news.investments = sortByRelevance(data.news.investments, 10);
data.news.expansions = sortByRelevance(data.news.expansions, 8);
data.news.partnerships = sortByRelevance(data.news.partnerships, 5);
data.news.public_markets = sortByRelevance(data.news.public_markets, 5);
data.news.divestitures = sortByRelevance(data.news.divestitures, 5);
data.news.general = sortByRelevance(data.news.general, 5);
data.news.top_stories = sortByRelevance(data.news.all_ma, 5);

// Generate summaries
const genSummary = (newsArr, defaultMsg) => {
  if (!newsArr || newsArr.length === 0) return defaultMsg;

  const topNews = newsArr.slice(0, 3);
  let parts = topNews.map(n => {
    let text = n.summaryEs && n.summaryEs.length > 30 ? n.summaryEs : n.titleEs || n.title;
    return text.replace(/\.+$/, '').trim();
  }).filter(t => t.length > 0);

  let summary = parts.join('. ');
  if (summary && !summary.endsWith('.')) summary += '.';

  if (summary.length > 500) {
    summary = summary.substring(0, 500);
    const lastSpace = summary.lastIndexOf(' ');
    if (lastSpace > 400) summary = summary.substring(0, lastSpace) + '...';
  }

  return summary || defaultMsg;
};

// Market summary
const coffee = data.markets.coffeeArabica;
let marketSummary = '';
if (coffee) {
  const dir = coffee.isPositive ? 'subió' : coffee.isNegative ? 'bajó' : 'se mantuvo estable';
  marketSummary = `El precio del Café Arábica ${dir} ${coffee.changePercent} esta semana, cerrando en $${coffee.price}/lb.`;
}
if (data.markets.trm) {
  marketSummary += ` TRM Colombia: $${data.markets.trm.formatted} COP/USD.`;
}
data.summaries.markets = marketSummary || 'Datos de mercado no disponibles.';

// Competitor summary
const competitorNames = Object.keys(data.competitors.mentioned);
if (competitorNames.length > 0) {
  const topCompetitors = Object.entries(data.competitors.mentioned)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 5)
    .map(([name, count]) => `${name} (${count})`)
    .join(', ');

  data.summaries.competitors = `Esta semana se identificaron ${data.news.competitors.length} noticias sobre competidores directos de Libertario. ` +
    `Competidores más activos: ${topCompetitors}. ` +
    genSummary(data.news.competitors, '');
} else {
  data.summaries.competitors = 'No se identificaron noticias relevantes sobre competidores esta semana. Se recomienda ampliar las fuentes de monitoreo.';
}

// News summaries by category
data.summaries.acquisitions = genSummary(data.news.acquisitions, 'No se reportaron adquisiciones significativas esta semana.');
data.summaries.investments = genSummary(data.news.investments, 'No se reportaron nuevas inversiones esta semana.');
data.summaries.expansions = genSummary(data.news.expansions, 'No se reportaron expansiones significativas esta semana.');
data.summaries.topStories = genSummary(data.news.top_stories, 'No hay noticias destacadas de M&A esta semana.');

// Executive summary
const totalMANews = data.news.all_ma.length;
const topIndustryCompanies = Object.entries(data.companies.mentioned)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5)
  .map(([name]) => name.charAt(0).toUpperCase() + name.slice(1));

data.summaries.executive = `Esta semana se identificaron ${totalMANews} noticias relacionadas con M&A en la industria del café especial. ` +
  (data.news.competitors.length > 0 ? `Se encontraron ${data.news.competitors.length} noticias sobre competidores directos. ` : '') +
  (data.news.acquisitions.length > 0 ? `Se reportaron ${data.news.acquisitions.length} adquisiciones. ` : '') +
  (data.news.investments.length > 0 ? `Se identificaron ${data.news.investments.length} movimientos de inversión. ` : '') +
  (topIndustryCompanies.length > 0 ? `Empresas más mencionadas: ${topIndustryCompanies.join(', ')}.` : '');

// Stats
data.statistics.maNewsCount = totalMANews;
data.statistics.competitorNewsCount = data.news.competitors.length;
data.companies.deals_count = data.news.acquisitions.length + data.news.mergers.length;

return [data];

// Coffee M&A Newsletter HTML Template v2.0
// MEJORADO: Sección dedicada de competidores

const data = $input.item.json;
const reportDate = data.reportDate || new Date().toLocaleDateString('es-CO', { 
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', timeZone: 'America/Bogota' 
});

// Helper functions
const newsHtml = (items, msg, showSummary = true, showCompetitors = false) => {
  if (!items?.length) return `<p style="color:#6c757d;font-style:italic;padding:10px;">${msg}</p>`;

  return '<div style="margin:0;">' + items.map(n => `
    <div style="padding:12px 0;border-bottom:1px solid #e9ecef;">
      <a href="${n.link}" style="color:#1a5f2a;text-decoration:none;font-weight:600;font-size:14px;line-height:1.4;display:block;" target="_blank">
        ${n.title}
      </a>
      ${n.titleEs && n.titleEs !== n.title ? `<p style="margin:4px 0 0;font-size:12px;color:#666;font-style:italic;">📝 ${n.titleEs}</p>` : ''}
      ${showCompetitors && n.competitors && n.competitors.length > 0 ? `
        <div style="margin:6px 0;">
          ${n.competitors.map(c => `<span style="display:inline-block;background:#e3f2fd;color:#1565c0;padding:2px 8px;border-radius:12px;font-size:10px;margin-right:5px;">${c.name} (${c.region})</span>`).join('')}
        </div>
      ` : ''}
      ${showSummary && n.summary ? `<p style="margin:6px 0 0;font-size:12px;color:#495057;line-height:1.5;">${n.summary.slice(0, 200)}${n.summary.length > 200 ? '...' : ''}</p>` : ''}
      <div style="margin-top:6px;font-size:11px;color:#888;">
        <span>${n.source || 'Fuente desconocida'}</span>
        ${n.pubDate ? ` • ${new Date(n.pubDate).toLocaleDateString('es-CO', { month: 'short', day: 'numeric' })}` : ''}
        ${n.relevance ? ` • Relevancia: ${'⭐'.repeat(Math.min(Math.floor(n.relevance/20), 5))}` : ''}
      </div>
    </div>
  `).join('') + '</div>';
};

const summaryBox = (text, bgColor = '#e8f5e9', borderColor = '#1a5f2a') => `
<div style="background:${bgColor};border-radius:8px;padding:14px 16px;margin-bottom:15px;border-left:4px solid ${borderColor};">
  <p style="margin:0;font-size:13px;color:#1a1a1a;line-height:1.6;"><strong>📌 Resumen:</strong> ${text}</p>
</div>`;

const sectionHeader = (icon, title, borderColor = '#1a5f2a') => `
<h2 style="color:#1a1a1a;font-size:16px;margin:25px 0 12px;padding-bottom:8px;border-bottom:3px solid ${borderColor};">
  ${icon} ${title}
</h2>`;

const coffee = data.markets?.coffeeArabica || {};
const trm = data.markets?.trm || {};
const news = data.news || {};
const sum = data.summaries || {};
const stats = data.statistics || {};
const companies = data.companies || {};
const competitorData = data.competitors || {};

// Competitor badges for the radar section
const competitorBadges = Object.entries(competitorData.mentioned || {})
  .sort((a, b) => b[1] - a[1])
  .slice(0, 10)
  .map(([name, count]) => {
    const info = competitorData.news_by_company?.[name]?.info || {};
    const regionColor = {
      'India': '#ff9800',
      'USA': '#2196f3',
      'USA/UK': '#9c27b0',
      'Australia': '#4caf50',
